class MsaSectorModel {
  const MsaSectorModel({
    required this.bearing,
    required this.alt,
    required this.radius,
  });

  final int bearing;
  final int alt;
  final int radius;

  factory MsaSectorModel.fromMap(Map<String, dynamic> map) {
    return MsaSectorModel(
      bearing: int.tryParse(map['bearing']?.toString() ?? '0') ?? 0,
      alt: int.tryParse(map['alt']?.toString() ?? '0') ?? 0,
      radius: int.tryParse(map['radius']?.toString() ?? '25') ?? 25,
    );
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'bearing': bearing,
        'alt': alt,
        'radius': radius,
      };
}

class MsaStationModel {
  const MsaStationModel({
    required this.ident,
    required this.country,
    required this.airport,
    required this.sectors,
  });

  final String ident;
  final String country;
  final String airport;
  final List<MsaSectorModel> sectors;

  factory MsaStationModel.fromMap(Map<String, dynamic> map) {
    final rawSectors = map['sectors'] as List<dynamic>? ?? [];
    return MsaStationModel(
      ident: map['ident']?.toString() ?? '',
      country: map['country']?.toString() ?? '',
      airport: map['airport']?.toString() ?? '',
      sectors: rawSectors
          .map((s) => MsaSectorModel.fromMap(Map<String, dynamic>.from(s)))
          .toList(),
    );
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'ident': ident,
        'country': country,
        'airport': airport,
        'sectors': sectors.map((s) => s.toMap()).toList(),
      };
}

